import base64, hashlib, json, pathlib, zlib
from datetime import datetime, timezone

root = pathlib.Path(".")
src_path = root / "dev/builds/1.3.26-dev-moica-cmts-fix56.json"
dst_rel = "dev/builds/1.3.26-dev-icon-personalization-polish-fix60.json"
dst_path = root / dst_rel
new_build = "1.3.26-dev-icon-personalization-polish-fix60"

overlays = {
  'background.js': '',
  'build.json': 'eNpNT80OgjAMvvMUZGeHGyAxnPUNjFcyoEjN3MgYxJ/47naSKJem/f7avqI4ZjO4Ea1hZcxkkiVpwTYBrifU7R/kLcwcG2v4QHprlMan8hhmq3HseYf3QizWplfGgA7mw/G8YBcw4JSHtlI+EKmgTCm4kCeZl7t9KajPqC7yaWhJ7Cpa6J1qgiX9Eg40qBGIuA20v0aN/lF12lr3OzZfZ1Sra+iH7Qi64wuVXOkRFr2jD0C2Tic=',
  'js/40-templates.js': '',
  'js/80-update-banner.js': '',
  'js/90-runtime-status.js': '',
  'js/96-ui-assets.js': '',
  'js/97-home-ui.js': '',
  'popup.html': '',
  'popup.js': '',
}

pkg = json.loads(src_path.read_text(encoding="utf-8"))
files = {}
base_order = []
for item in pkg["files"]:
    raw = base64.b64decode(item["content_base64"], validate=True)
    assert len(raw) == item["size"]
    assert hashlib.sha256(raw).hexdigest() == item["sha256"]
    path = item["path"]
    if path in {"updater.html","updater.js"}:
        continue
    files[path] = raw
    base_order.append(path)

for path, compressed_b64 in overlays.items():
    files[path] = zlib.decompress(base64.b64decode(compressed_b64))

# New portable assets are JavaScript-only so every historical supported updater can install them.
new_paths = ["js/96-ui-assets.js", "js/97-home-ui.js"]
desired_order = [p for p in base_order if p != "integrity-manifest.json"]
for p in new_paths:
    if p not in desired_order:
        # keep helper scripts with the JS payload before root metadata/UI files when possible
        insert_at = next((i for i,x in enumerate(desired_order) if x in {"manifest.json","popup.html","popup.js"}), len(desired_order))
        desired_order.insert(insert_at,p)
desired_order.append("integrity-manifest.json")

allowed = set(desired_order)
extra = sorted(set(files) - allowed)
assert not extra, f"unexpected package files: {extra}"
missing = [p for p in desired_order if p != "integrity-manifest.json" and p not in files]
assert not missing, f"missing package files: {missing}"
assert not any(p.startswith("home.") or p.startswith("icons/") for p in desired_order)

integrity = {
    "schema": 1,
    "version": "1.3.26",
    "channel": "DEV",
    "build": new_build,
    "files": {path: hashlib.sha256(files[path]).hexdigest() for path in desired_order if path != "integrity-manifest.json"}
}
files["integrity-manifest.json"] = (json.dumps(integrity, ensure_ascii=False, indent=2) + "\n").encode("utf-8")

pkg.update({
    "schema": 1,
    "app": "VIENA NOC Tools",
    "version": "1.3.26",
    "build": new_build,
    "channel": "DEV",
    "generated_at": datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00","Z"),
    "remove": []
})
pkg["files"] = [{
    "path": path,
    "size": len(files[path]),
    "sha256": hashlib.sha256(files[path]).hexdigest(),
    "content_base64": base64.b64encode(files[path]).decode("ascii")
} for path in desired_order]
raw_pkg = (json.dumps(pkg, ensure_ascii=False, indent=2) + "\n").encode("utf-8")
dst_path.write_bytes(raw_pkg)
package_sha = hashlib.sha256(raw_pkg).hexdigest()

pointer_path = root / "dev/self-update.json"
pointer = json.loads(pointer_path.read_text(encoding="utf-8"))
pointer.update({
    "version": "1.3.26",
    "build": new_build,
    "channel": "DEV",
    "package_url": f"https://raw.githubusercontent.com/fdevvv/viena-noc-tools-updates/refs/heads/main/{dst_rel}",
    "package_sha256": package_sha,
    "notes": [
        "Nuevo popup corporativo compacto con acceso a la vista completa de VIENA NOC Tools.",
        "Nueva vista completa con herramientas, personalización, actualizaciones y diagnóstico reutilizando el estado existente.",
        "Editor de botones integrado y personalización del icono con tres variantes, preservando storage, plantillas y updater actuales."
    ]
})
pointer_path.write_text(json.dumps(pointer, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

history_path = root / "dev/history.json"
history = json.loads(history_path.read_text(encoding="utf-8"))
history["current_build"] = new_build
history["current_package"] = dst_rel
note = "fix60 introduces the popup/full-view UX redesign, integrated button editor and icon personalization using only portable updater-safe paths."
if note not in history.get("notes", []):
    history.setdefault("notes", []).append(note)
history_path.write_text(json.dumps(history, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

assert len(pkg["files"]) == len(base_order) + 2
for required in ["popup.html","popup.js","js/96-ui-assets.js","js/97-home-ui.js","js/40-templates.js"]:
    assert required in files
assert json.loads(files["manifest.json"].decode("utf-8"))["version"] == "1.3.26"
print(json.dumps({"package": dst_rel, "sha256": package_sha, "build": new_build, "files": len(pkg["files"])}, indent=2))